model = env.get("VERDA_MODEL") or "nemotron-3.5-super-vl"
def strip(s, keys):
    s = copy.deepcopy(s)
    def walk(o):
        if isinstance(o, dict):
            for k in keys: o.pop(k, None)
            for v in o.values(): walk(v)
    walk(s); return s
for label, schema in [("full", m._SCHEMA), ("no uniqueItems", strip(m._SCHEMA, ["uniqueItems"])),
                      ("no uniqueItems/maxLength", strip(m._SCHEMA, ["uniqueItems", "maxLength"])),
                      ("no uniq/maxLen/min/max", strip(m._SCHEMA, ["uniqueItems", "maxLength", "minimum", "maximum"]))]:
    try:
        r = c.chat.completions.create(model=model, max_tokens=200, messages=[{"role": "user", "content": "Return the JSON with empty lists and confidence 1."}],
            response_format={"type": "json_schema", "json_schema": {"name": "image_diff", "schema": schema}},
            extra_body={"chat_template_kwargs": {"enable_thinking": False}})
        print(label, "OK", r.choices[0].message.content[:200])
    except Exception as e:
        print(label, "FAIL", type(e).__name__, str(e)[:500])
EOF
